require "socket"
require "net/http"
require "json"
require "uri"
require "timeout"
require "websocket/driver"

class CDPClient
  class DriverIO
    attr_reader :url
    def initialize(url, socket)
      @url, @socket = url, socket
    end
    def write(data)
      @socket.write(data)
    end
  end

  def initialize(ws_url)
    uri = URI.parse(ws_url)
    @sock = TCPSocket.new(uri.host, uri.port)
    @driver = WebSocket::Driver.client(DriverIO.new(ws_url, @sock))
    @messages = Queue.new
    @id = 0
    open_q = Queue.new

    @driver.on(:open) { open_q << true }
    @driver.on(:message) do |event|
      msg = JSON.parse(event.data)
      @messages << msg if msg["id"]
    end

    @reader = Thread.new do
      loop do
        data = @sock.readpartial(65536)
        @driver.parse(data)
      end
    rescue EOFError, IOError
    end

    @driver.start
    Timeout.timeout(5) { open_q.pop }
  end

  def call(method, params = {})
    @id += 1
    req_id = @id
    @driver.text({ id: req_id, method: method, params: params }.to_json)
    loop do
      msg = Timeout.timeout(10) { @messages.pop }
      return msg["result"] if msg["id"] == req_id
    end
  end

  def eval_js(expr)
    res = call("Runtime.evaluate", { expression: expr, returnByValue: true, awaitPromise: true })
    raise "JS error: #{res.inspect}" if res["exceptionDetails"]
    res.dig("result", "value")
  end

  def navigate(url)
    call("Page.navigate", { url: url })
    wait_until { eval_js("document.readyState === 'complete' && location.href === #{url.to_json}") }
  end

  def wait_until(timeout: 10)
    deadline = Time.now + timeout
    loop do
      val = yield
      return val if val
      if Time.now > deadline
        loc = eval_js("location.href") rescue "?"
        html = eval_js("document.body?.innerText?.slice(0, 300)") rescue "?"
        raise "Timed out at #{loc}: #{html}"
      end
      sleep 0.1
    end
  end

  def close
    @sock.close rescue nil
    @reader.kill rescue nil
  end
end

